SELECT 
FROM fund_plan


        AND plan_name LIKE CONCAT('%', #{params.planName}, '%')


        AND plan_type = #{params.planType}


        AND plan_status = #{params.planStatus}


        AND org_id = #{params.orgId}


        AND start_date >= #{params.startDate}


        AND end_date <= #{params.endDate}


ORDER BY create_time DESC

SELECT 
FROM fund_plan
WHERE plan_no = #{planNo}

SELECT 
FROM fund_plan
WHERE org_id = #{orgId} AND plan_status = 'COMPLETED'

    AND complete_date >= #{startDate}


    AND complete_date <= #{endDate}

ORDER BY complete_date DESC

SELECT COUNT(*)
FROM fund_plan


        AND plan_type = #{params.planType}


        AND plan_status = #{params.planStatus}


        AND org_id = #{params.orgId}


        AND start_date >= #{params.startDate}


        AND end_date <= #{params.endDate}

SELECT COALESCE(SUM(total_income), 0)
FROM fund_plan


        AND plan_type = #{params.planType}


        AND plan_status = #{params.planStatus}


        AND org_id = #{params.orgId}


        AND start_date >= #{params.startDate}


        AND end_date <= #{params.endDate}

SELECT COALESCE(SUM(total_expense), 0)
FROM fund_plan


        AND plan_type = #{params.planType}


        AND plan_status = #{params.planStatus}


        AND org_id = #{params.orgId}


        AND start_date >= #{params.startDate}


        AND end_date <= #{params.endDate}

SELECT COALESCE(SUM(net_cash_flow), 0)
FROM fund_plan


        AND plan_type = #{params.planType}


        AND plan_status = #{params.planStatus}


        AND org_id = #{params.orgId}


        AND start_date >= #{params.startDate}


        AND end_date <= #{params.endDate}

SELECT COALESCE(AVG(completion_rate), 0)
FROM fund_plan
WHERE plan_status = 'COMPLETED'

    AND plan_type = #{params.planType}


    AND org_id = #{params.orgId}


    AND complete_date >= #{params.startDate}


    AND complete_date <= #{params.endDate}

SELECT 
    COUNT(*) as totalCount,
    COALESCE(SUM(total_income), 0) as totalIncome,
    COALESCE(SUM(total_expense), 0) as totalExpense,
    COALESCE(SUM(net_cash_flow), 0) as totalNetCashFlow,
    COALESCE(AVG(completion_rate), 0) as avgCompletionRate
FROM fund_plan


        AND plan_type = #{params.planType}


        AND plan_status = #{params.planStatus}


        AND org_id = #{params.orgId}


        AND start_date >= #{params.startDate}


        AND end_date <= #{params.endDate}

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as planCount, COALESCE(SUM(total_income), 0) as totalIncome, COALESCE(SUM(total_expense), 0) as totalExpense, COALESCE(SUM(net_cash_flow), 0) as netCashFlow FROM fund_plan WHERE org_id = #{orgId}
AND create_time >= #{startDate}
AND create_time <= #{endDate}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month ASC

SELECT plan_type, COUNT(*) as planCount, COALESCE(SUM(total_income), 0) as totalIncome, COALESCE(SUM(total_expense), 0) as totalExpense, COALESCE(SUM(net_cash_flow), 0) as netCashFlow, COALESCE(AVG(completion_rate), 0) as avgCompletionRate FROM fund_plan WHERE org_id = #{orgId}
AND plan_type = #{planType}
AND YEAR(create_time) = #{year}
GROUP BY plan_type ORDER BY planCount DESC

SELECT plan_status, COUNT(*) as count, COALESCE(SUM(total_income), 0) as totalIncome, COALESCE(SUM(total_expense), 0) as totalExpense, COALESCE(AVG(completion_rate), 0) as avgCompletionRate FROM fund_plan WHERE org_id = #{orgId}
AND create_time >= #{startDate}
AND create_time <= #{endDate}
GROUP BY plan_status ORDER BY count DESC

SELECT COUNT(*) > 0
FROM fund_plan
WHERE plan_no = #{planNo}

SELECT COUNT(*) > 0
FROM fund_plan
WHERE plan_name = #{planName} AND org_id = #{orgId}

SELECT 
FROM fund_plan
WHERE plan_id = #{planId}

SELECT 'DETAIL_COUNT' as checkType, CASE WHEN COUNT(d.detail_id) = 0 THEN 'ERROR' ELSE 'OK' END as status, CASE WHEN COUNT(d.detail_id) = 0 THEN '计划明细不能为空' ELSE '计划明细检查通过' END as message FROM fund_plan p LEFT JOIN fund_plan_detail d ON p.plan_id = d.plan_id WHERE p.plan_id = #{planId}
UNION ALL
SELECT 'AMOUNT_CONSISTENCY' as checkType, CASE WHEN ABS(p.total_income - COALESCE(SUM(CASE WHEN d.business_type = 'INCOME' THEN d.planned_amount ELSE 0 END), 0)) > 0.01 OR ABS(p.total_expense - COALESCE(SUM(CASE WHEN d.business_type = 'EXPENSE' THEN d.planned_amount ELSE 0 END), 0)) > 0.01 THEN 'ERROR' ELSE 'OK' END as status, CASE WHEN ABS(p.total_income - COALESCE(SUM(CASE WHEN d.business_type = 'INCOME' THEN d.planned_amount ELSE 0 END), 0)) > 0.01 OR ABS(p.total_expense - COALESCE(SUM(CASE WHEN d.business_type = 'EXPENSE' THEN d.planned_amount ELSE 0 END), 0)) > 0.01 THEN '计划金额与明细金额不一致' ELSE '金额一致性检查通过' END as message FROM fund_plan p LEFT JOIN fund_plan_detail d ON p.plan_id = d.plan_id WHERE p.plan_id = #{planId} GROUP BY p.plan_id, p.total_income, p.total_expense
